# ───────────────────────────── F-MONITOR HYPOTHESIS (template) ─────────────────
# These are SHALLOW monitoring runs Forager fires per open position. Each gets a
# simple 3-hypothesis response shaped by the market type. We avoid hand-crafting
# all 8 because they re-research the same questions as B did.

F_MONITOR_TEMPLATE = lambda seed: [
    {
        "direction": "NO",
        "title": "Status quo persists — no new confirming event",
        "hypothesis_text": (
            f"Monitoring search for: {seed[:120]}. Base rate for short-horizon "
            "questions like this resolving YES with no specific confirming event "
            "is low. Absent fresh news of the predicted event, NO is the default."
        ),
        "confidence": 0.65,
        "evidence_score": 0.50,
        "key_items": [1, 2, 3],
    },
    {
        "direction": "UNCERTAIN",
        "title": "Insufficient fresh evidence to update prior",
        "hypothesis_text": (
            "Forager SHALLOW pass returned generic search results. No specific "
            "kill-criterion-confirming or thesis-confirming source surfaced. "
            "Maintain prior thesis confidence pending next monitoring cycle."
        ),
        "confidence": 0.50,
        "evidence_score": 0.40,
        "key_items": [1, 2],
    },
    {
        "direction": "YES",
        "title": "Tail risk — event could still surprise",
        "hypothesis_text": (
            "8-10 days remaining; geopolitical / political surprises possible. "
            "Small probability of late-cycle reversal must be reserved."
        ),
        "confidence": 0.15,
        "evidence_score": 0.30,
        "key_items": [1, 3],
    },
]


def write_response(handoff_path: str, response: dict, generator: str) -> None:
    out_path = handoff_path.rsplit(".json", 1)[0] + ".response.json"
    payload = {
        "task": "response",
        "for": os.path.basename(handoff_path),
        "generated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "generator": generator,
        "response": response,
    }
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)
    # Mark source handoff as processed
    try:
        with open(handoff_path, encoding="utf-8") as f:
            src = json.load(f)
        src["status"] = "processed"
        src["response_file"] = os.path.basename(out_path)
        with open(handoff_path, "w", encoding="utf-8") as f:
            json.dump(src, f, ensure_ascii=False, indent=2, default=str)
    except Exception as e:  # noqa: BLE001
        print(f"  WARN: failed to mark source processed: {e}")


def match_b_batch(seed: str) -> list[dict] | None:
    for key, hyps in B_BATCH_HYPOTHESES.items():
        if seed.startswith(key):
            return hyps
    return None


def process_hypothesis_files() -> dict:
    import glob
    stats = {"b_batch": 0, "f_monitor_template": 0, "skipped": 0}
    for f in sorted(glob.glob(os.path.join(HANDOFF_DIR, "hypothesis_*.json"))):
        if f.endswith(".response.json"):
            continue
        with open(f, encoding="utf-8") as fh:
            data = json.load(fh)
        if data.get("status") == "processed":
            stats["skipped"] += 1
            continue
        seed = data.get("seed_query", "")
        # Hand-authored B-batch?
        hyps = match_b_batch(seed)
        if hyps:
            write_response(
                f,
                {"hypotheses": hyps},
                generator="claude-opus-4-7-inline-handauthored",
            )
            stats["b_batch"] += 1
            print(f"  [B-batch ✓] {os.path.basename(f)} — {len(hyps)} hypotheses")
            continue
        # Else: F monitor (per-position SHALLOW)
        hyps = F_MONITOR_TEMPLATE(seed)
        write_response(
            f,
            {"hypotheses": hyps},
            generator="claude-opus-4-7-template-monitor",
        )
        stats["f_monitor_template"] += 1
        print(f"  [F-template] {os.path.basename(f)}")
    return stats


