# ──────────────────── Inject B-batch hypotheses into ForagerStore ──────────────

def inject_b_batch_to_forager_store() -> int:
    """Find each B-batch thread and replace/augment its hypotheses with the
    hand-authored ones. Returns count of threads updated."""
    try:
        import importlib.util
        from dotenv import load_dotenv
        load_dotenv(".env")
        db_path = os.environ.get("FORAGER_DB_PATH", "").strip()
        if not db_path or not os.path.exists(db_path):
            print(f"  [inject] FORAGER_DB_PATH not set or missing: {db_path}")
            return 0
        from forager.memory.sqlite_store import SQLiteForagerStore
        from forager.models import Hypothesis
        store = SQLiteForagerStore(db_path)
        # Map candidate question prefix → condition_id from forager_queue_auto
        spec = importlib.util.spec_from_file_location("q", os.path.join(os.path.dirname(__file__), "forager_queue_auto.py"))
        m = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(m)
        queue = getattr(m, "forager_queue", None) or getattr(m, "CANDIDATES", [])
        injected = 0
        for cand in queue:
            cid = cand["condition_id"]
            question = cand["question"]
            # Find matching hypothesis set
            hyps_for_market = None
            for key, hyps in B_BATCH_HYPOTHESES.items():
                if key in question or question.startswith(key.split(" ", 1)[0]):
                    if any(k in question for k in key.split() if len(k) > 3):
                        hyps_for_market = hyps
                        break
            if not hyps_for_market:
                continue
            # Find latest thread for this market
            try:
                packet = store.latest_packet_for_market(cid)
                if not packet:
                    continue
                tid = packet.thread_id if hasattr(packet, "thread_id") else packet.get("thread_id")
            except Exception:
                continue
            # Inject each hypothesis
            for h in hyps_for_market:
                hyp = Hypothesis(
                    thread_id=tid,
                    title=h["title"][:120],
                    hypothesis_text=h["hypothesis_text"][:800],
                    confidence=float(h["confidence"]),
                    evidence_score=float(h["evidence_score"]),
                    signal_relevance_score=0.75,
                    created_by_agent="claude-opus-4-7-handauthored",
                )
                try:
                    store.add_hypothesis(hyp)
                except Exception as e:
                    print(f"  [inject] failed for {cid[:16]}: {e}")
            injected += 1
            print(f"  [inject] {len(hyps_for_market)} hypotheses → thread {tid[:16]} ({question[:50]})")
        return injected
    except Exception as e:
        print(f"  [inject] error: {e}")
        return 0


def main():
    print("=== Process LLM handoffs ===\n")
    print("Processing hypothesis files...")
    h_stats = process_hypothesis_files()
    print(f"  B-batch (hand-authored): {h_stats['b_batch']}")
    print(f"  F-monitor (template):    {h_stats['f_monitor_template']}")
    print(f"  Already processed:       {h_stats['skipped']}")

    print("\nProcessing dossier_draft files...")
    d_count = process_dossier_files()
    print(f"  Total: {d_count}")

    print("\nProcessing monitoring_draft files...")
    m_count = process_monitoring_files()
    print(f"  Total: {m_count}")

    print("\nInjecting B-batch hypotheses into ForagerStore...")
    inj = inject_b_batch_to_forager_store()
    print(f"  Threads updated: {inj}")

    total = h_stats["b_batch"] + h_stats["f_monitor_template"] + d_count + m_count
    print(f"\n✓ Total handoffs processed: {total}")


if __name__ == "__main__":
    main()
